class Regione 
{
    constructor(nome, codice) {
        this.nome = nome;
        this.cod_reg = codice;
    }
}

class Provincia 
{
    constructor(nome,regione,sigla) {
        this.nome = nome;
        this.regione = regione;
        this.sigla = sigla;
    }   
}

class Comune
{
    constructor(nome, pro_com, provincia) {
        this.nome = nome;
        this.pro_com = pro_com;
        this.provincia = provincia;
    }
    
}



